SELECT json_build_object(
 'columns', (SELECT coalesce(json_agg(json_build_object('name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) ORDER BY column_name),'[]'::json) FROM information_schema.columns WHERE table_schema='public' AND table_name='orders' AND column_name IN ('work_items','lemana_import_meta')),
 'functions', (SELECT coalesce(json_agg(json_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'md5',md5(p.prosrc),'language',l.lanname,'security_definer',p.prosecdef,'volatility',p.provolatile,'parallel',p.proparallel,'config',p.proconfig,'owner',pg_get_userbyid(p.proowner),'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.proname,p.oid),'[]'::json) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('bos_order_identity_numbers','bos_lemana_number_guard','bos_import_lemana_order')),
 'constraints', (SELECT coalesce(json_agg(json_build_object('name',conname,'valid',convalidated,'definition',pg_get_constraintdef(oid)) ORDER BY conname),'[]'::json) FROM pg_constraint WHERE conrelid='public.orders'::regclass AND conname='orders_work_items_array'),
 'indexes', (SELECT coalesce(json_agg(json_build_object('name',c.relname,'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY c.relname),'[]'::json) FROM pg_class c JOIN pg_index i ON i.indexrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relname='orders_lemana_no_index'),
 'triggers', (SELECT coalesce(json_agg(json_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid)) ORDER BY tgname),'[]'::json) FROM pg_trigger WHERE tgrelid='public.orders'::regclass AND tgname IN ('aa_bos_lemana_number_guard'))
)
